"""Parse a Claude Code session JSONL file into structured records.

Format (observed in `~/.claude/projects/<slug>/<session>.jsonl`):
- `type=user`: user message (may include slash commands as inline `<command-name>` tags)
- `type=assistant`: model turn; carries `message.content[]` (thinking / text / tool_use blocks),
  `message.model`, `message.usage`
- `type=system`: hook output, etc.
- `type=ai-title`: model-generated title for the session
- `type=file-history-snapshot`, `type=pr-link`, `type=attachment`, `type=queue-operation`,
  `type=last-prompt`: housekeeping; mostly ignored.

The parser stays close to the raw shape — `aggregator.py` does the phase / metric synthesis.
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from datetime import datetime
from pathlib import Path

_COMMAND_RE = re.compile(r"<command-name>([^<]+)</command-name>")
_COMMAND_ARGS_RE = re.compile(r"<command-args>([^<]*)</command-args>")
_ASK_USER_ANSWER_PREFIX = "User has answered your questions:"
_LOCAL_COMMAND_STDOUT_RE = re.compile(r"<local-command-stdout>([^<]*)</local-command-stdout>")
# A real slash command starts with `/`, followed by [a-zA-Z][a-zA-Z0-9_-]* and either
# whitespace or end-of-message. Rejects file paths like `/Users/foo/bar` (multiple `/`)
# and avoids false-positive splits on mid-flow user-pasted paths.
_SLASH_CMD_RE = re.compile(r"^/([a-zA-Z][a-zA-Z0-9_:-]*)(?=\s|$)")


@dataclass
class ToolUse:
    name: str
    input: dict


@dataclass
class Usage:
    input_tokens: int = 0
    output_tokens: int = 0
    cache_creation_input_tokens: int = 0
    cache_read_input_tokens: int = 0


@dataclass
class Turn:
    """One assistant or user turn, normalised."""
    role: str  # "user" | "assistant" | "system"
    timestamp: datetime
    text: str = ""
    thinking: str = ""
    tool_uses: list[ToolUse] = field(default_factory=list)
    model: str | None = None
    usage: Usage = field(default_factory=Usage)
    slash_command: str | None = None
    command_args: str | None = None  # raw content of <command-args> tag if present
    is_meta: bool = False
    is_tool_result_only: bool = False  # user turn whose only content is tool_result blocks
    is_human_answer: bool = False  # AskUserQuestion answer — synthetic shape but real human input


@dataclass
class Session:
    session_id: str
    project_slug: str
    title: str | None
    started_at: datetime | None
    ended_at: datetime | None
    cwd: str | None
    git_branch: str | None
    turns: list[Turn]
    raw_count: int

    @property
    def duration_seconds(self) -> int:
        if not self.started_at or not self.ended_at:
            return 0
        return int((self.ended_at - self.started_at).total_seconds())


def _parse_iso(s: str) -> datetime | None:
    if not s:
        return None
    try:
        # "2026-04-22T15:23:11.987Z" → datetime
        return datetime.fromisoformat(s.replace("Z", "+00:00"))
    except Exception:
        return None


def _content_blocks(message: dict) -> list[dict]:
    content = message.get("content")
    if isinstance(content, list):
        return content
    if isinstance(content, str):
        return [{"type": "text", "text": content}]
    return []


def parse_session(jsonl_path: Path) -> Session:
    """Read one session JSONL file. Tolerant: skips malformed lines."""
    turns: list[Turn] = []
    title: str | None = None
    started_at: datetime | None = None
    ended_at: datetime | None = None
    session_id = ""
    cwd: str | None = None
    git_branch: str | None = None
    raw_count = 0

    with jsonl_path.open(encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            raw_count += 1
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue

            t = rec.get("type")
            ts = _parse_iso(rec.get("timestamp", ""))
            if ts:
                if started_at is None or ts < started_at:
                    started_at = ts
                if ended_at is None or ts > ended_at:
                    ended_at = ts

            if t == "ai-title":
                title = rec.get("title") or rec.get("message", {}).get("title")
                continue

            sid = rec.get("sessionId")
            if sid:
                session_id = sid
            cwd = rec.get("cwd") or cwd
            git_branch = rec.get("gitBranch") or git_branch

            if t == "user":
                turn = _turn_from_user(rec, ts)
                if turn is not None:
                    turns.append(turn)
            elif t == "assistant":
                turn = _turn_from_assistant(rec, ts)
                if turn is not None:
                    turns.append(turn)
            elif t == "system":
                turn = _turn_from_system(rec, ts)
                if turn is not None:
                    turns.append(turn)

    return Session(
        session_id=session_id or jsonl_path.stem,
        project_slug=jsonl_path.parent.name,
        title=title,
        started_at=started_at,
        ended_at=ended_at,
        cwd=cwd,
        git_branch=git_branch,
        turns=turns,
        raw_count=raw_count,
    )


def _turn_from_user(rec: dict, ts: datetime | None) -> Turn | None:
    msg = rec.get("message") or {}
    text_parts: list[str] = []
    slash_cmd: str | None = None

    has_text_block = False
    has_tool_result_block = False

    for block in _content_blocks(msg):
        bt = block.get("type")
        if bt == "text":
            has_text_block = True
            txt = block.get("text", "") or ""
            text_parts.append(txt)
        elif bt == "tool_result":
            has_tool_result_block = True
            # tool_result on user side; treat as text for context
            content = block.get("content")
            if isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get("type") == "text":
                        text_parts.append(c.get("text", ""))
            elif isinstance(content, str):
                text_parts.append(content)

    full = "\n".join(text_parts)
    # A turn that carries ONLY tool_result blocks (no text block) is a synthetic
    # tool-result message from Claude Code, not a real human intervention.
    is_tool_result_only = has_tool_result_block and not has_text_block

    # Special case: AskUserQuestion answers are delivered as tool_result content
    # but represent REAL human input ("User has answered your questions: ...").
    # Mark these so the aggregator can surface them as interventions.
    is_human_answer = (
        is_tool_result_only
        and _ASK_USER_ANSWER_PREFIX in full
    )
    cmd_match = _COMMAND_RE.search(full)
    if cmd_match:
        # `<command-name>` may carry a colon-separated path like
        # `intake-requirement:intake-requirement` — keep only the leaf segment
        slash_cmd = cmd_match.group(1).strip().lstrip("/")
        if ":" in slash_cmd:
            slash_cmd = slash_cmd.split(":")[0]

    # Extract `<command-args>` if present — the argument(s) the user passed
    # after the slash command (e.g. story id, file path).
    command_args: str | None = None
    args_match = _COMMAND_ARGS_RE.search(full)
    if args_match:
        raw_args = args_match.group(1).strip()
        if raw_args:
            command_args = raw_args
    if not slash_cmd:
        # Look for "/arh-intake-requirement X" prefix in the visible portion of the prompt
        # (after stripping wrapping tags). Tight regex avoids splitting on file paths.
        stripped = re.sub(r"<[^>]+>", "", full).strip()
        m = _SLASH_CMD_RE.match(stripped)
        if m:
            slash_cmd = m.group(1)

    return Turn(
        role="user",
        timestamp=ts or datetime.utcfromtimestamp(0),
        text=full,
        slash_command=slash_cmd,
        command_args=command_args,
        is_meta=bool(rec.get("isMeta")),
        is_tool_result_only=is_tool_result_only,
        is_human_answer=is_human_answer,
    )


def _turn_from_assistant(rec: dict, ts: datetime | None) -> Turn | None:
    msg = rec.get("message") or {}
    text_parts: list[str] = []
    thinking_parts: list[str] = []
    tool_uses: list[ToolUse] = []

    for block in _content_blocks(msg):
        bt = block.get("type")
        if bt == "thinking":
            thinking_parts.append(block.get("thinking", "") or "")
        elif bt == "text":
            text_parts.append(block.get("text", "") or "")
        elif bt == "tool_use":
            tool_uses.append(ToolUse(
                name=block.get("name", "?"),
                input=block.get("input", {}) or {},
            ))

    usage = msg.get("usage") or {}
    return Turn(
        role="assistant",
        timestamp=ts or datetime.utcfromtimestamp(0),
        text="\n".join(text_parts),
        thinking="\n".join(thinking_parts),
        tool_uses=tool_uses,
        model=msg.get("model"),
        usage=Usage(
            input_tokens=int(usage.get("input_tokens") or 0),
            output_tokens=int(usage.get("output_tokens") or 0),
            cache_creation_input_tokens=int(usage.get("cache_creation_input_tokens") or 0),
            cache_read_input_tokens=int(usage.get("cache_read_input_tokens") or 0),
        ),
    )


def _turn_from_system(rec: dict, ts: datetime | None) -> Turn | None:
    msg = rec.get("message") or {}
    blocks = _content_blocks(msg)
    text_parts = []
    for b in blocks:
        if isinstance(b, dict) and b.get("type") == "text":
            text_parts.append(b.get("text", ""))
    return Turn(
        role="system",
        timestamp=ts or datetime.utcfromtimestamp(0),
        text="\n".join(text_parts),
    )


def list_project_sessions(project_dir: Path) -> list[Path]:
    """List `*.jsonl` session files in a project dir, newest first."""
    if not project_dir.is_dir():
        return []
    files = [p for p in project_dir.glob("*.jsonl") if p.is_file()]
    files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return files


def list_projects(projects_root: Path) -> list[Path]:
    """List project dirs under `~/.claude/projects/`."""
    if not projects_root.is_dir():
        return []
    return sorted([p for p in projects_root.iterdir() if p.is_dir()])
